-- Application-generated UUIDs, UTC ISO-8601 timestamps, integer minor-unit money.
-- SQLite-specific configuration lives in the adapter, not this relational model.
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, timezone TEXT NOT NULL, avatar TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE terms (id TEXT PRIMARY KEY, name TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE households (id TEXT PRIMARY KEY, name TEXT NOT NULL, term_id TEXT NOT NULL REFERENCES terms(id), host_id TEXT NOT NULL REFERENCES users(id), timezone TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity > 0), theme TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE memberships (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('learner','host')), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(household_id, user_id));
CREATE TABLE sessions (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), title TEXT NOT NULL, description TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('scheduled','completed','cancelled')), meeting_url TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(ends_at > starts_at));
CREATE TABLE assignments (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('prepare','practice','reflect')), due_at TEXT NOT NULL, week INTEGER NOT NULL CHECK(week BETWEEN 0 AND 6), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE submissions (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), learner_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','submitted')), completed INTEGER NOT NULL CHECK(completed IN (0,1)), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(assignment_id, learner_id));
CREATE TABLE feedback (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published')), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(submission_id, author_id));
CREATE TABLE applications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), goal TEXT NOT NULL, availability TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('new','contacted','enrolled')), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE enrollments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), term_id TEXT NOT NULL REFERENCES terms(id), household_id TEXT NOT NULL REFERENCES households(id), plan TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor >= 0), currency TEXT NOT NULL, payment_status TEXT NOT NULL CHECK(payment_status IN ('pending','paid')), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,term_id));
CREATE TABLE mutation_receipts (actor_id TEXT NOT NULL REFERENCES users(id), command_id TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(actor_id,command_id));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX sessions_household_start ON sessions(household_id,starts_at);
CREATE INDEX assignments_household_due ON assignments(household_id,due_at);
CREATE INDEX submissions_learner ON submissions(learner_id);
CREATE INDEX feedback_submission ON feedback(submission_id);
CREATE INDEX applications_status ON applications(status);
CREATE INDEX memberships_user ON memberships(user_id);
